def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context['supply'])
    day = int(day_context['day'])
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    rich_aggressive = 0
    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            prev = opp.get('previous_trace', {})
            bid = prev.get('bid') if prev else None
            if bid is not None:
                prev_bids.append(float(bid))
            if opp.get('budget', 0) > 500 and opp.get('hp', 0) >= 7:
                rich_aggressive += 1

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = (MAX_SUPPLY - supply) / float(MAX_SUPPLY - MIN_SUPPLY)
    if scarcity < 0:
        scarcity = 0.0
    if scarcity > 1:
        scarcity = 1.0

    urgency = 0.0
    if hp <= 2:
        urgency += 1.0
    elif hp <= 4:
        urgency += 0.6
    elif hp <= 6:
        urgency += 0.25

    if no_water_days >= 2:
        urgency += 0.8
    elif no_water_days == 1:
        urgency += 0.35

    if day >= 8:
        urgency += 0.2

    pressure = 0.45 * scarcity + 0.55 * urgency

    if hp <= 2 or no_water_days >= 2:
        bid = max(58.0, min(92.0, highest_prev * 0.72 + 8.0))
    elif supply >= 23 and hp >= 7:
        bid = 8.0 + 6.0 * scarcity
    elif supply <= 17:
        bid = 28.0 + 18.0 * pressure + min(highest_prev, 90.0) * 0.12
    else:
        bid = 16.0 + 20.0 * pressure + avg_prev * 0.08

    if rich_aggressive >= 2 and hp >= 6 and supply >= 20:
        bid *= 0.72

    if highest_prev >= 140 and hp >= 5 and no_water_days == 0:
        bid *= 0.7

    soft_cap = DAILY_SALARY * 0.95
    if hp >= 5 and no_water_days == 0:
        bid = min(bid, soft_cap)

    if day == 1 and hp == 10:
        bid = min(bid, 24.0)

    bid = max(0.0, min(float(budget), float(bid)))
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 9
    DAILY_SALARY = 90
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = float(day_context.get('supply', 0.0))
    day = int(day_context.get('day', 0))

    hp = float(my_status.get('hp', 0.0))
    budget = float(my_status.get('budget', 0.0))
    no_water_days = int(my_status.get('no_water_days', 0))

    alive_opponents = []
    for k, o in opponents_status.items():
        if o.get('alive', False):
            alive_opponents.append(o)

    if not alive_opponents:
        return max(0.0, min(budget, DAILY_SALARY * 0.4))

    # Reaction to yesterday's bids (immediate pressure signal)
    yesterday_bids = []
    for o in alive_opponents:
        prev = o.get('previous_trace', {})
        if isinstance(prev, dict):
            b = prev.get('bid', None)
            if b is not None:
                try:
                    yesterday_bids.append(float(b))
                except Exception:
                    pass

    highest_prev_bid = max(yesterday_bids) if yesterday_bids else 0.0

    # Estimate how competitive the day is: higher supply reduces urgency
    # (supply is between 15 and 25)
    supply_norm = 0.0
    if MAX_SUPPLY > MIN_SUPPLY:
        supply_norm = (supply - MIN_SUPPLY) / float(MAX_SUPPLY - MIN_SUPPLY)
    supply_norm = max(0.0, min(1.0, supply_norm))

    # Base bid: if I'm healthy, undercut; if low HP or accumulating dry days, bid up.
    # Use highest_prev_bid to avoid being outbid when others are aggressive.
    urgency = 0.0
    if hp <= 1.5:
        urgency = 1.0
    elif hp <= 3.0:
        urgency = 0.75
    elif hp <= 5.0:
        urgency = 0.45
    else:
        urgency = 0.25

    if no_water_days >= 2:
        urgency = max(urgency, 0.85)

    # Target competitiveness threshold: others' yesterday max suggests their typical winning range.
    # If they were bidding high, we slightly trail; if not, we bid moderate.
    if highest_prev_bid >= DAILY_SALARY * 0.85:
        # They were very aggressive yesterday; match near their level but not exceed too much.
        target = highest_prev_bid - 5.0 + (urgency * 6.0)
    else:
        target = max(DAILY_SALARY * (0.45 + 0.25 * urgency), highest_prev_bid * 0.65 + 10.0)

    # Adjust for supply: more supply -> can bid less to secure water.
    target = target * (0.95 + 0.10 * (1.0 - supply_norm))

    # Hard caps to avoid bankruptcy; also ensure non-negative.
    # Since water requirement is 9, don't overcommit beyond a fraction of budget.
    max_affordable = budget * 0.35
    if budget <= 0:
        return 0.0

    # If my HP is critical, allow higher spending up to 0.75 of budget.
    if hp <= 2.0 or no_water_days >= 3:
        max_affordable = budget * 0.75

    bid = min(max_affordable, target)

    # If target is too low relative to likely competition, bump slightly.
    if highest_prev_bid > 0 and bid < highest_prev_bid * 0.6 and urgency >= 0.6:
        bid = min(max_affordable, highest_prev_bid * 0.75)

    # Final clamp
    if bid < 0.0:
        bid = 0.0
    return float(bid)

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150
    EPISODE_DAYS = 10

    my_current_budget = my_status['budget']
    my_current_hp = my_status['hp']
    current_supply = day_context['supply']
    current_day = day_context['day']

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_current_budget, DAILY_SALARY * 0.2)

    bid = DAILY_SALARY * 0.65 # Moderate base bid

    eric_status = None
    alex_status = None
    for opp_id, opp in opponents_status.items():
        if opp_id == "Eric":
            eric_status = opp
        elif opp_id == "Alex":
            alex_status = opp

    eric_prev_bid = 0
    eric_budget = 0
    if eric_status and eric_status['alive']:
        prev = eric_status.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            eric_prev_bid = prev['bid']
        eric_budget = eric_status['budget']

    alex_prev_bid = 0
    alex_budget = 0
    if alex_status and alex_status['alive']:
        prev = alex_status.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            alex_prev_bid = prev['bid']
        alex_budget = alex_status['budget']

    # Adjust bid based on my HP
    if my_current_hp <= 2:
        bid = DAILY_SALARY * 0.95
    elif my_current_hp <= 4:
        bid = DAILY_SALARY * 0.85

    # Adjust bid based on supply scarcity
    if current_supply <= WATER_REQ + 2:
        bid *= 1.15
    elif current_supply <= WATER_REQ + 5:
        bid *= 1.05

    # Counter Eric's aggressive bidding if he has budget
    if eric_prev_bid > 0 and eric_budget >= DAILY_SALARY * 1.5:
        if eric_prev_bid > DAILY_SALARY * 0.7:
            bid = max(bid, eric_prev_bid * 1.05)
        else:
            bid = max(bid, eric_prev_bid * 1.01)
    elif eric_prev_bid > 0: # Eric bid high but might not have huge budget
        bid = max(bid, eric_prev_bid * 1.01)

    # Counter Alex, but less aggressively due to his low budget
    if alex_prev_bid > 0 and alex_budget > 0 and alex_budget < DAILY_SALARY:
        if alex_prev_bid > DAILY_SALARY * 0.7 and current_supply <= WATER_REQ + 5:
            bid = max(bid, alex_prev_bid * 1.02)
        else:
            bid = max(bid, alex_prev_bid * 0.95)

    # Late game desperation
    if current_day > EPISODE_DAYS * 0.7:
        if my_current_hp <= 5:
            bid = DAILY_SALARY * 0.99
        elif my_current_hp > 8:
            bid *= 0.9

    final_bid = min(my_current_budget, bid)

    if final_bid < DAILY_SALARY * 0.1 and my_current_budget > 0:
        final_bid = min(my_current_budget, DAILY_SALARY * 0.1)
    elif my_current_budget == 0:
        final_bid = 0

    return final_bid
